public class Main {
    public static void main(String[] args) {
        int total = 17;
        int boxes = total / 5; //~ Both sides are ints, so / does whole-number division: 17 / 5 is 3. The .4 is thrown away.
        int left = total % 5; //~ % gives the remainder: 17 = 5 × 3 + 2, so left is 2.
        System.out.println(boxes + " boxes, " + left + " left"); //~ Print both parts.
    }
}

